const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // Cairns city center approximate coordinates
    const cairns = ee.Geometry.Point(145.77, -16.92);

    // To find a point 100km offshore east of Cairns:
    // We can define a bounding box around Cairns and then pick a point.
    // A simpler approach for this scale is to adjust longitude directly.
    // At ~-17 deg latitude, 1 degree longitude is about 111 km * cos(-17 deg) = 106 km.
    // So, 100 km east is roughly 100/106 = 0.94 degrees longitude east.
    const offshorePoint = ee.Geometry.Point(145.77 + 0.94, -16.92);

    const startYearHistorical = 2003;
    const endYearHistorical = 2014;
    const targetMonth = 3; // March

    const startYearCurrent = 2022;
    const endYearCurrent = 2022;

    const scale = 5000; // OISST resolution is 0.25 degrees, roughly 25km. Use a scale of 5000m to be safe.

    // 2. Data Acquisition
    const sstCollection = ee.ImageCollection('NOAA/CDR/OISST/V2');

    // Filter historical data for March (2003-2014)
    let historicalSSTs = sstCollection
      .filter(ee.Filter.calendarRange(targetMonth, targetMonth, 'month'))
      .filter(ee.Filter.calendarRange(startYearHistorical, endYearHistorical, 'year'))
      .filterBounds(offshorePoint);

    // Filter current data for March 2022
    let currentSSTs = sstCollection
      .filter(ee.Filter.calendarRange(targetMonth, targetMonth, 'month'))
      .filter(ee.Filter.calendarRange(startYearCurrent, endYearCurrent, 'year'))
      .filterBounds(offshorePoint);

    // Check if collections are empty
    const historicalSize = await historicalSSTs.size().getInfo();
    const currentSize = await currentSSTs.size().getInfo();

    if (historicalSize === 0 || currentSize === 0) {
      console.log(`Historical March images (2003-2014): ${historicalSize}`);
      console.log(`Current March images (2022): ${currentSize}`);
      console.log("C1: Empty Collection (No images found for one or both periods)");
      return;
    }

    // 3. Processing: Calculate mean SST for each period
    const meanHistoricalSST = historicalSSTs.mean().select('sst'); // Select 'sst' band and calculate mean
    const meanCurrentSST = currentSSTs.mean().select('sst'); // Select 'sst' band and calculate mean

    // Calculate the mean SST at the offshore point
    const currentSSTValue = await meanCurrentSST.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: offshorePoint,
      scale: scale,
      maxPixels: 1e9
    }).get('sst').getInfo();

    const historicalSSTValue = await meanHistoricalSST.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: offshorePoint,
      scale: scale,
      maxPixels: 1e9
    }).get('sst').getInfo();

    // 4. Validation for C3 (Calculation Failure)
    if (currentSSTValue === null || isNaN(currentSSTValue) ||
        historicalSSTValue === null || isNaN(historicalSSTValue)) {
      console.log(`Current March 2022 SST: ${currentSSTValue}`);
      console.log(`Historical March (2003-2014) SST: ${historicalSSTValue}`);
      console.log("C3: Calculation Failure (Result is None, NaN, or invalid)");
      return;
    }

    // Check for C2 (No Valid Pixels) - implicit if values are null. If values are 0, that's valid.
    // The OISST dataset is dense, so getting 0 valid pixels at sea is highly unlikely,
    // but the null check above covers the main failure mode for reduceRegion.

    // Calculate the difference
    const temperatureDifference = currentSSTValue - historicalSSTValue;
    const absoluteDifference = Math.abs(temperatureDifference);

    // 5. Validation & Final Answer
    console.log(`Historical March (2003-2014) Avg SST: ${historicalSSTValue.toFixed(2)} °C`);
    console.log(`Current March (2022) Avg SST: ${currentSSTValue.toFixed(2)} °C`);
    console.log(`Temperature Difference (Current - Historical): ${temperatureDifference.toFixed(2)} °C`);
    console.log(`Absolute Difference: ${absoluteDifference.toFixed(2)} °C`);

    if (absoluteDifference > 1) {
      console.log("A: Yes");
    } else {
      console.log("B: No");
    }

  } catch (e) {
    console.error("D: An error occurred: ", e);
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
